        "YEARLY": "ARE EAR ERA LAY RAY YEA EARL REAL RELY YEAR EARLY LAYER RELAY YEARLY",
    ]

    static let bases: [String] = all.keys.sorted()

    /// The known words for a base (upper-case), or [].
    static func words(for base: String) -> [String] {
        (all[base] ?? "").split(separator: " ").map(String.init)
    }
}
